/**
 * @jest-environment Node
 */

const { add, subtract, multiply, divide, factorial, clamp } = require('./calculator');

describe('Calculator', () => {

    // Test basic arithmetic operations (add, subtract, multiply) with positive inputs.
    describe('Basic Arithmetic Operations', () => {
        it('should correctly add two positive numbers', () => {
            expect(add(2, 3)).toBe(5);
            expect(add(100, 50)).toBe(150);
        });

        it('should correctly subtract two positive numbers (a - b)', () => {
            expect(subtract(5, 2)).toBe(3);
            expect(subtract(10, 1)).toBe(9);
        });

        it('should correctly multiply two positive numbers', () => {
            expect(multiply(4, 5)).toBe(20);
            expect(multiply(10, 10)).toBe(100);
        });
    });

    // Test division by zero failure case and exception handling for the divide function.
    describe('Divide Function (Error Handling)', () => {
        it('should throw an Error when dividing by zero', () => {
            const a = 5;
            const b = 0;
            expect(() => divide(a, b)).toThrow('Division by zero is not allowed');
            // Verify type of thrown error if needed, but checking the message suffices per typical requirements.
        });

        it('should return correct result when dividing by non-zero number', () => {
            expect(divide(10, 2)).toBe(5);
            expect(divide(7, 3)).toBeCloseTo(2.3333); // Use toBeCloseTo for float comparison
        });
    });

    // Verify factorial calculation edge cases: N=0, N=1, and negative input detection.
    describe('Factorial Function', () => {
        it('should return 1 for N=0 (edge case)', () => {
            expect(factorial(0)).toBe(1);
        });

        it('should return 1 for N=1 (edge case)', () => {
            expect(factorial(1)).toBe(1);
        });

        it('should correctly calculate factorial for positive integers', () => {
            expect(factorial(3)).toBe(6); // 3 * 2 * 1
            expect(factorial(5)).toBe(120); // 5! = 120
        });

        it('should throw an Error for negative input (negative detection)', () => {
            const n = -1;
            expect(() => factorial(n)).toThrow('Factorial is not defined for negative numbers');
        });
    });


    // Validate clamp functionality against boundaries (min/max) and test the invalid argument condition where min > max.
    describe('Clamp Function', () => {

        it('should return the value itself if it is within [min, max]', () => {
            expect(clamp(5, 0, 10)).toBe(5);
        });

        it('should return min when value is below the minimum boundary', () => {
            // Value (-5) < Min (0)
            expect(clamp(-5, 0, 10)).toBe(0);
        });

        it('should return max when value is above the maximum boundary', () => {
            // Value (20) > Max (10)
            expect(clamp(20, 0, 10)).toBe(10);
        });

        it('should handle clamping with negative boundaries', () => {
            // Test case: Min = -10, Max = -5. Value = -20. Should return min (-10).
            expect(clamp(-20, -10, -5)).toBe(-10);
        });

        it('should throw an Error when the minimum boundary is greater than the maximum boundary', () => {
            // Min (10) > Max (5)
            const min = 10;
            const max = 5;
            expect(() => clamp(1, min, max)).toThrow('min must not be greater than max');
        });
    });

});
